/**
 * Script to generate per-team (BA, Dev, QA) schedule from JIRA CSV export.
 *
 * - Input:  outputs/jira-export.csv (generated by extract-jira-estimates.ts)
 * - Output: outputs/jira-team-schedule.csv (ready for Excel Gantt)
 *
 * For each ticket, this script:
 * - Derives a base estimate from Story Points / Original Estimate.
 * - Splits it into BA / Dev / QA effort shares.
 * - Calculates sequential start/end timestamps per team assuming working
 *   hours 09:00–13:00 and 14:00–18:00 on working days (Mon–Fri).
 *
 * Usage:
 *   npx ts-node generate-team-schedule-from-jira.ts
 */

import { readFileSync, writeFileSync } from 'fs';
// csv-parse does not ship full TypeScript typings in this project context.
// Suppress type checking for this import while still using the runtime module.
// @ts-ignore
import { parse } from 'csv-parse/sync';
import { defaultConfig } from './src/config/types';
import { validateAndProcessEstimate } from './src/processors/estimate-processor';

type CsvRow = Record<string, string>;

interface TeamSegmentRow {
  issueKey: string;
  summary: string;
  issueType: string;
  status: string;
  jiraTeam: string;
  role: string; // Dynamic role name from workSequence
  executionTeam: string;
  estimateHours: number;
  /**
   * Ticket-level estimate in Story Points (same for all role segments of a ticket).
   */
  storyPoints?: number;
  latestSprint?: string;
  epicLink?: string;
  start: string; // Local datetime string "YYYY-MM-DD HH:mm"
  end: string;   // Local datetime string "YYYY-MM-DD HH:mm"
}

interface TicketEstimate {
  storyPoints?: number;
  baseHours: number;
}

interface SubtaskMatchCriteria {
  titleTags?: string[];
  components?: string[];
  labels?: string[];
}

interface RoleConfig {
  role: string;
  estimateMethod: 'percentage' | 'subtasks';
  percentage?: number; // Required if estimateMethod is 'percentage'
  subtaskMatch?: SubtaskMatchCriteria; // Required if estimateMethod is 'subtasks'
  statuses: string[];
  executionTeam: string;
}

interface TeamConfig {
  id: string;
  name: string;
  includeInSchedule?: boolean; // Default: true
  velocity?: number;
  velocityPeriod?: string;
  members?: string[];
  matchRules?: {
    jiraTeam?: string[];
    issueTypes?: string[];
    statuses?: string[];
    components?: string[];
    labels?: string[];
    summaryText?: string[];
  };
  workSequence?: RoleConfig[];
}

interface TeamsConfig {
  projectStartDate?: string;
  projectReschedulingDate?: string;
  sprintDurationDays?: number;
  /**
   * Optional list of issue types that should be included in schedule planning.
   * Example: ["Story"]
   */
  plannedIssueTypes?: string[];
  /**
   * List of Fix Versions that should be included in the schedule.
   * Example: ["PSME MVP 1.0"]
   */
  fixVersions?: string[];
  /**
   * Gantt chart grouping type. Determines how tasks are grouped in the Gantt visualization.
   * - "epicSprint": Group by Epic, then by Sprint (default)
   * - "sprintTeam": Group by Sprint, then by Team (legacy)
   * Example: "epicSprint"
   */
  ganttGrouping?: 'epicSprint' | 'sprintTeam';
  teams?: TeamConfig[] | Record<string, Omit<TeamConfig, 'id'>>;
  /**
   * Work types - can be array (backward compatibility) or object with meaningful keys
   * Array: ["PSME-FE", "PSME-BE"]
   * Object: { "PSME-FE": { "name": "PSME-FE" }, ... }
   */
  workTypes?: string[] | Record<string, { name: string }>;
  /**
   * Mapping of work types to their work sequences.
   * Key: work type name (e.g., "PSME-FE")
   * Value: array of role configurations
   */
  workTypeSequences?: Record<string, RoleConfig[]>;
}

interface VelocityContext {
  sprintDurationDays: number;
  defaultVelocity: number;
  baVelocity?: number;
  qaVelocity?: number;
  jiraTeamVelocities: Record<string, number>;
}

interface SprintInfo {
  endDate?: string;
  completeDate?: string;
}

/**
 * Loads team configuration (velocity, sprint duration, etc.) from schedule_config.json.
 */
function loadTeamsConfigFromFile(): TeamsConfig {
  try {
    const raw = readFileSync('schedule_config.json', 'utf-8');
    const parsed = JSON.parse(raw) as TeamsConfig;
    return parsed;
  } catch {
    // If config is missing or invalid, return empty object and rely on defaults
    return {};
  }
}

/**
 * Converts teams from object or array format to array format for processing.
 */
function getTeamsArray(teams: TeamsConfig['teams']): TeamConfig[] {
  if (!teams) {
    return [];
  }
  
  if (Array.isArray(teams)) {
    return teams;
  }
  
  // Convert object to array, adding id from key
  return Object.entries(teams).map(([id, team]) => ({
    ...team,
    id,
  }));
}

/**
 * Builds a velocity context map from the teams configuration.
 */
function buildVelocityContext(config: TeamsConfig): VelocityContext {
  const sprintDurationDays =
    typeof config.sprintDurationDays === 'number' && config.sprintDurationDays > 0
      ? config.sprintDurationDays
      : 10;

  const teams = getTeamsArray(config.teams);
  const velocities = teams
    .map((t) => t.velocity)
    .filter((v): v is number => typeof v === 'number' && v > 0);

  const defaultVelocity = velocities.length > 0 ? velocities[0] : 10;

  let baVelocity: number | undefined;
  let qaVelocity: number | undefined;
  const jiraTeamVelocities: Record<string, number> = {};

  for (const team of teams) {
    const velocity = team.velocity && team.velocity > 0 ? team.velocity : defaultVelocity;

    if (team.id === 'team-ba' || team.name === 'BA Team') {
      baVelocity = velocity;
    }

    if (team.id === 'team-qa' || team.name === 'QA Team') {
      qaVelocity = velocity;
    }

    const jiraTeams = team.matchRules?.jiraTeam;
    if (Array.isArray(jiraTeams)) {
      for (const jt of jiraTeams) {
        if (jt && !jiraTeamVelocities[jt]) {
          jiraTeamVelocities[jt] = velocity;
        }
      }
    }
  }

  return {
    sprintDurationDays,
    defaultVelocity,
    baVelocity,
    qaVelocity,
    jiraTeamVelocities,
  };
}

/**
 * Resolves the effective velocity for a specific role and Jira team.
 */
function getVelocityForSegment(
  role: string,
  jiraTeam: string,
  ctx: VelocityContext,
  roleVelocities?: Record<string, number>
): number {
  // Check role-specific velocities first
  if (roleVelocities && roleVelocities[role]) {
    return roleVelocities[role];
  }

  // Legacy support for BA/QA roles
  if (role === 'BA' && ctx.baVelocity) {
    return ctx.baVelocity;
  }

  if (role === 'QA' && ctx.qaVelocity) {
    return ctx.qaVelocity;
  }

  // For Dev role or if jiraTeam is specified, use team velocity
  if (jiraTeam && ctx.jiraTeamVelocities[jiraTeam]) {
    return ctx.jiraTeamVelocities[jiraTeam];
  }

  return ctx.defaultVelocity;
}

/**
 * Scales raw effort hours using team velocity and sprint duration so that:
 *   Duration (days) ≈ (Estimate (SP) / Velocity) * SprintDuration
 * assuming 1 Story Point ≈ 8 hours and effortHours ≈ SP * 8.
 *
 * In practice, this reduces/increases calendar duration per team based on velocity.
 */
function scaleHoursWithVelocity(
  effortHours: number,
  velocity: number,
  ctx: VelocityContext
): number {
  if (!isFinite(effortHours) || effortHours <= 0) {
    return 0;
  }

  const v = velocity > 0 ? velocity : ctx.defaultVelocity;
  const sprintDays = ctx.sprintDurationDays > 0 ? ctx.sprintDurationDays : 10;

  // Derived from: durationDays = (SP / v) * sprintDays; effortHours ≈ SP * 8; hoursPerDay ≈ 8
  // => durationHours ≈ effortHours * sprintDays / v
  return effortHours * (sprintDays / v);
}

