// Input/Output paths
const INPUT_CSV_PATH = 'outputs/jira-export.csv';
const OUTPUT_CSV_PATH = 'outputs/jira-team-schedule.csv';
const SPRINTS_CSV_PATH = 'outputs/jira-export-sprints.csv';

/**
 * Simple helper to extract a field from a CSV row with alternative names.
 */
function extractField(
  row: CsvRow,
  primaryName: string,
  alternativeNames: string[] = []
): string | undefined {
  if (row[primaryName] !== undefined) {
    return row[primaryName];
  }

  for (const alt of alternativeNames) {
    if (row[alt] !== undefined) {
      return row[alt];
    }
  }

  return undefined;
}

/**
 * Loads sprint data from sprints CSV and builds a lookup map.
 * Returns a Map: sprintName -> SprintInfo
 */
function loadSprintMap(): Map<string, SprintInfo> {
  const sprintMap = new Map<string, SprintInfo>();

  try {
    const sprintsContent = readFileSync(SPRINTS_CSV_PATH, 'utf-8');
    const sprintRecords = parse(sprintsContent, {
      columns: true,
      skip_empty_lines: true,
      trim: true,
      relax_column_count: true,
    }) as CsvRow[];

    for (const sprintRow of sprintRecords) {
      const sprintName = sprintRow['Name'] || '';
      const endDate = sprintRow['End Date'] || undefined;
      const completeDate = sprintRow['Complete Date'] || undefined;

      if (sprintName) {
        sprintMap.set(sprintName, {
          endDate,
          completeDate,
        });
      }
    }

    console.log(`Loaded ${sprintMap.size} sprints from ${SPRINTS_CSV_PATH}`);
  } catch (error) {
    console.warn(
      `Warning: Could not load sprints CSV from ${SPRINTS_CSV_PATH}. Sprint-based ordering will be limited.`
    );
  }

  return sprintMap;
}

/**
 * Extracts the latest sprint name from a comma-separated sprint field.
 * Returns the last sprint name in the list (most recent), or undefined if empty.
 */
function getLatestSprint(sprintField: string | undefined): string | undefined {
  if (!sprintField || sprintField.trim() === '') {
    return undefined;
  }

  const sprints = sprintField.split(',').map((s) => s.trim()).filter((s) => s.length > 0);
  return sprints.length > 0 ? sprints[sprints.length - 1] : undefined;
}

/**
 * Determines if a ticket is completed.
 * Returns true if ticket's Status Category is "DONE".
 */
function isCompletedTicket(row: CsvRow): boolean {
  const statusCategory = extractField(row, 'Status Category', ['statusCategory', 'Status Category']);

  // Check if Status Category is "DONE" (case-insensitive)
  if (statusCategory && statusCategory.toUpperCase() === 'DONE') {
    return true;
  }

  return false;
}

/**
 * Gets the sprint end date for a sprint name from the sprint map.
 * Returns the endDate string or undefined if sprint not found.
 */
function getSprintEndDate(
  sprintName: string | undefined,
  sprintMap: Map<string, SprintInfo>
): string | undefined {
  if (!sprintName) {
    return undefined;
  }

  const sprintInfo = sprintMap.get(sprintName);
  return sprintInfo?.endDate;
}

/**
 * Returns true if the given date is a weekend (Saturday or Sunday).
 */
function isWeekend(date: Date): boolean {
  const day = date.getDay(); // 0 = Sunday, 6 = Saturday
  return day === 0 || day === 6;
}

/**
 * Moves the date forward to the start (09:00) of the next working day (Mon–Fri).
 */
function startOfNextWorkingDay(date: Date): Date {
  const d = new Date(date.getTime());
  // Move to next day, 09:00
  d.setDate(d.getDate() + 1);
  d.setHours(9, 0, 0, 0);

  // Skip weekends
  while (isWeekend(d)) {
    d.setDate(d.getDate() + 1);
    d.setHours(9, 0, 0, 0);
  }

  return d;
}

/**
 * Ensures the given Date is aligned to working time:
 * - If weekend → move to next working day 09:00.
 * - If before 09:00 → set to 09:00.
 * - If between 13:00–14:00 → set to 14:00.
 * - If after 18:00 → move to next working day 09:00.
 * - If within [09:00–13:00) or [14:00–18:00) → unchanged.
 */
function normalizeToWorkingTime(input: Date): Date {
  let d = new Date(input.getTime());

  // Skip weekends
  if (isWeekend(d)) {
    return startOfNextWorkingDay(d);
  }

  const hours = d.getHours() + d.getMinutes() / 60;

  if (hours < 9) {
    d.setHours(9, 0, 0, 0);
  } else if (hours >= 13 && hours < 14) {
    d.setHours(14, 0, 0, 0);
  } else if (hours >= 18) {
    d = startOfNextWorkingDay(d);
  }

  // If now on weekend after adjustment, move again
  if (isWeekend(d)) {
    return startOfNextWorkingDay(d);
  }

  return d;
}

/**
 * Adds working hours to a start Date, respecting:
 * - Working days: Monday–Friday.
 * - Working hours: 09:00–13:00 and 14:00–18:00.
 * - Lunch break: 13:00–14:00 (non-working).
 *
 * @param start - Start Date (will be normalized to working time)
 * @param hours - Working hours to add (can be fractional)
 * @returns End Date aligned to working time
 */
function addWorkingHours(start: Date, hours: number): Date {
  if (hours <= 0) {
    return normalizeToWorkingTime(start);
  }

  let remaining = hours;
  let current = normalizeToWorkingTime(start);

  while (remaining > 1e-6) {
    current = normalizeToWorkingTime(current);

    // Ensure we are on a working day
    if (isWeekend(current)) {
      current = startOfNextWorkingDay(current);
      continue;
    }

    const currentHours = current.getHours() + current.getMinutes() / 60;
    let blockEndHour: number | null = null;

    if (currentHours >= 9 && currentHours < 13) {
      blockEndHour = 13;
    } else if (currentHours >= 14 && currentHours < 18) {
      blockEndHour = 18;
    } else {
      // Outside working blocks, normalize again
      current = normalizeToWorkingTime(current);
      continue;
    }

    const availableInBlock = blockEndHour - currentHours;
    const used = Math.min(availableInBlock, remaining);

    // Advance time by 'used' hours
    current = new Date(current.getTime() + used * 60 * 60 * 1000);
    remaining -= used;

    if (remaining <= 1e-6) {
      break;
    }

    // If block is exhausted but hours remain, move to next working segment
    current = normalizeToWorkingTime(current);
  }

  return normalizeToWorkingTime(current);
}

/**
 * Formats Date into "YYYY-MM-DD HH:mm" for Excel-friendly import.
 */
function formatDateTimeLocal(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  return `${year}-${month}-${day} ${hours}:${minutes}`;
}

/**
 * Loads project start / rescheduling date from team configuration.
 * Falls back to "2025-01-01" if configuration is missing.
 */
function loadProjectStartDateTime(config: TeamsConfig): Date {
  let projectStartDate = '2025-01-01';

  if (config) {
    projectStartDate =
      config.projectReschedulingDate ||
      config.projectStartDate ||
      projectStartDate;
  }

  let start = new Date(`${projectStartDate}T09:00:00`);

  // If the chosen date is a weekend, move to next working day
  if (isWeekend(start)) {
    start = startOfNextWorkingDay(start);
  } else {
    start.setHours(9, 0, 0, 0);
  }

  return start;
}

/**
 * Finds the matching team for a ticket based on Team, Label, Summary text, and Component.
 * Priority order:
 * 1. Team field (jiraTeam) - if present and matches
 * 2. Labels - if Team is empty or doesn't match
 * 3. Summary text - if Labels don't match or are empty
 * 4. Component - only if none of the above matched
 *
 * Returns the team's jiraTeam value (first match from jiraTeam array) or empty string if no match.
 * Stops checking once the first match is found.
 */
function findMatchingTeam(
  row: CsvRow,
  teamsConfig: TeamsConfig
): string {
  const jiraTeam = extractField(row, 'Team', ['team', 'Jira Team']) || '';
  const component = extractField(row, 'Component', ['component']) || '';
  const labels = extractField(row, 'Labels', ['labels']) || '';
  const summary = extractField(row, 'Summary', ['Title', 'title']) || '';

  const teams = getTeamsArray(teamsConfig.teams);

  // Filter teams by includeInSchedule flag (default: true)
  const includedTeams = teams.filter(team => team.includeInSchedule !== false);

  // First, try to match by Team field (jiraTeam) - if present
  if (jiraTeam && jiraTeam.trim() !== '') {
    for (const team of includedTeams) {
      const teamJiraTeams = team.matchRules?.jiraTeam;
      if (Array.isArray(teamJiraTeams) && teamJiraTeams.includes(jiraTeam)) {
        return jiraTeam;
      }
    }
  }

  // If Team is empty or doesn't match, try Labels
  if (labels && labels.trim() !== '') {
    for (const team of includedTeams) {
      const teamLabels = team.matchRules?.labels;
      if (Array.isArray(teamLabels) && teamLabels.length > 0) {
        // Labels field may contain comma-separated values
        const labelList = labels.split(',').map(l => l.trim());
        const matches = labelList.some(l => 
          teamLabels.some(tl => 
            l.toLowerCase() === tl.toLowerCase() || 
            l.toLowerCase().includes(tl.toLowerCase()) ||
            tl.toLowerCase().includes(l.toLowerCase())
          )
        );
        if (matches) {
          const teamJiraTeams = team.matchRules?.jiraTeam;
          if (Array.isArray(teamJiraTeams) && teamJiraTeams.length > 0) {
            return teamJiraTeams[0];
          }
          return team.name;
        }
      }
    }
  }

  // If Labels don't match or are empty, try Summary text
  if (summary && summary.trim() !== '') {
    const summaryLower = summary.toLowerCase();
    for (const team of includedTeams) {
      const teamSummaryTexts = team.matchRules?.summaryText;
      if (Array.isArray(teamSummaryTexts) && teamSummaryTexts.length > 0) {
        const matches = teamSummaryTexts.some(st => 
          summaryLower.includes(st.toLowerCase())
        );
        if (matches) {
          const teamJiraTeams = team.matchRules?.jiraTeam;
          if (Array.isArray(teamJiraTeams) && teamJiraTeams.length > 0) {
            return teamJiraTeams[0];
          }
          return team.name;
        }
      }
    }
  }

  // If SummaryText doesn't match, try Component (only if none of the above matched)
  if (component && component.trim() !== '') {
    for (const team of includedTeams) {
      const teamComponents = team.matchRules?.components;
      if (Array.isArray(teamComponents) && teamComponents.length > 0) {
        // Component field may contain comma-separated values
        const componentList = component.split(',').map(c => c.trim());
        const matches = componentList.some(c => 
          teamComponents.some(tc => 
            c.toLowerCase() === tc.toLowerCase() || 
            c.toLowerCase().includes(tc.toLowerCase()) ||
            tc.toLowerCase().includes(c.toLowerCase())
          )
        );
        if (matches) {
          // Return the first jiraTeam from this team's config, or team name as fallback
          const teamJiraTeams = team.matchRules?.jiraTeam;
          if (Array.isArray(teamJiraTeams) && teamJiraTeams.length > 0) {
            return teamJiraTeams[0];
          }
          return team.name;
        }
      }
    }
  }

  // No match found, return original jiraTeam or empty
  return jiraTeam;
}

/**
 * Interface for fake sprint information.
 */
interface FakeSprint {
  name: string;
  startDate: string;
  endDate: string;
  assignedTickets: CsvRow[];
}

/**
 * Generates fake sprints for tickets without sprints and assigns tickets to them.
 * Returns array of fake sprints and updates the records with assigned sprint names.
 */
function generateFakeSprints(
  records: CsvRow[],
  sprintMap: Map<string, SprintInfo>,
  teamsConfig: TeamsConfig
): FakeSprint[] {
  // Find latest sprint end date
  let latestEndDate: Date | null = null;
  let latestSprintNumber = 0;

  sprintMap.forEach((sprintInfo, sprintName) => {
    if (sprintInfo.endDate) {
      const endDate = new Date(sprintInfo.endDate);
      if (!latestEndDate || endDate > latestEndDate) {
        latestEndDate = endDate;
      }
    }
    
    // Extract sprint number from name (e.g., "PSME Sp 10" -> 10)
    const match = sprintName.match(/\bSp\s+(\d+)\b/i);
    if (match && match[1]) {
      const sprintNum = parseInt(match[1], 10);
      if (sprintNum > latestSprintNumber) {
        latestSprintNumber = sprintNum;
      }
    }
  });

  // If no sprints found, start from project rescheduling date or start date
  if (!latestEndDate) {
    const projectStart = teamsConfig.projectReschedulingDate || teamsConfig.projectStartDate || '2025-12-22';
    latestEndDate = new Date(projectStart);
    latestEndDate.setHours(9, 0, 0, 0);
  }

  // Find all tickets without sprints
  const ticketsWithoutSprints: CsvRow[] = [];
  for (const row of records) {
    const sprintField = extractField(row, 'Sprint', ['sprint']);
    const latestSprint = getLatestSprint(sprintField);
    if (!latestSprint) {
      ticketsWithoutSprints.push(row);
    }
  }

  if (ticketsWithoutSprints.length === 0) {
    console.log('No tickets without sprints found. Skipping fake sprint generation.');
    return [];
  }

  console.log(`Found ${ticketsWithoutSprints.length} tickets without sprints. Generating fake sprints...`);

  // Group tickets by team and calculate total story points per team
  const teamTickets = new Map<string, Array<{ row: CsvRow; storyPoints: number }>>();
  const velocityContext = buildVelocityContext(teamsConfig);
  const sprintDurationDays = velocityContext.sprintDurationDays;

  for (const row of ticketsWithoutSprints) {
    const jiraTeam = findMatchingTeam(row, teamsConfig) || 'Unknown';
    const estimate = getTicketEstimate(row, 0);
    const storyPoints = estimate.storyPoints || 0;

    if (!teamTickets.has(jiraTeam)) {
      teamTickets.set(jiraTeam, []);
    }
    teamTickets.get(jiraTeam)!.push({ row, storyPoints });
  }

  // Generate fake sprints for each team
  const fakeSprints: FakeSprint[] = [];
  let currentSprintNumber = latestSprintNumber + 1;
  let currentStartDate = new Date(latestEndDate.getTime());
  
  // Move to next working day
  currentStartDate.setDate(currentStartDate.getDate() + 1);
  while (isWeekend(currentStartDate)) {
    currentStartDate.setDate(currentStartDate.getDate() + 1);
  }
  currentStartDate.setHours(9, 0, 0, 0);

  // Track the latest sprint end date across all teams to ensure sequential sprints
  let globalLatestEndDate = new Date(currentStartDate.getTime());

  teamTickets.forEach((tickets, jiraTeam) => {
    const teamVelocity = velocityContext.jiraTeamVelocities[jiraTeam] || velocityContext.defaultVelocity;
    const totalStoryPoints = tickets.reduce((sum, t) => sum + t.storyPoints, 0);
    const sprintsNeeded = Math.ceil(totalStoryPoints / teamVelocity);

    console.log(`Team ${jiraTeam}: ${totalStoryPoints} story points, ${teamVelocity} velocity → ${sprintsNeeded} sprints needed`);

    let remainingTickets = [...tickets];
    let currentCapacity = 0;
    let currentSprintTickets: CsvRow[] = [];

    for (let sprintIdx = 0; sprintIdx < sprintsNeeded || remainingTickets.length > 0; sprintIdx++) {
      // Calculate sprint dates - start from global latest end date
      const sprintStart = new Date(globalLatestEndDate.getTime());
      sprintStart.setDate(sprintStart.getDate() + 1);
      while (isWeekend(sprintStart)) {
        sprintStart.setDate(sprintStart.getDate() + 1);
      }
      sprintStart.setHours(9, 0, 0, 0);
      
      const sprintEnd = new Date(sprintStart);
      
      // Add sprint duration (working days)
      let workingDaysAdded = 0;
      while (workingDaysAdded < sprintDurationDays) {
        sprintEnd.setDate(sprintEnd.getDate() + 1);
        if (!isWeekend(sprintEnd)) {
          workingDaysAdded++;
        }
      }
      sprintEnd.setHours(18, 0, 0, 0);

      // Assign tickets to this sprint
      while (remainingTickets.length > 0 && currentCapacity < teamVelocity) {
        const ticket = remainingTickets[0];
        const ticketSP = ticket.storyPoints;
        
        if (currentCapacity + ticketSP <= teamVelocity || currentSprintTickets.length === 0) {
          // Add ticket to current sprint
          currentSprintTickets.push(ticket.row);
          currentCapacity += ticketSP;
          remainingTickets.shift();
        } else {
          // Ticket doesn't fit, start new sprint
          break;
        }
      }

      if (currentSprintTickets.length > 0) {
        const sprintName = `PSME Sp ${currentSprintNumber} (${formatSprintDate(sprintStart)}-${formatSprintDate(sprintEnd)})`;
        
        // Assign sprint to tickets
        for (const ticketRow of currentSprintTickets) {
          // Update the Sprint field in the row
          const existingSprint = extractField(ticketRow, 'Sprint', ['sprint']) || '';
          ticketRow['Sprint'] = existingSprint ? `${existingSprint}, ${sprintName}` : sprintName;
        }

        fakeSprints.push({
          name: sprintName,
          startDate: sprintStart.toISOString(),
          endDate: sprintEnd.toISOString(),
          assignedTickets: currentSprintTickets,
        });

        console.log(`  Created ${sprintName}: ${currentSprintTickets.length} tickets, ${currentCapacity} story points`);
      }

      // Prepare for next sprint
      currentSprintNumber++;
      
      // Update global latest end date for next sprint
      globalLatestEndDate = new Date(sprintEnd.getTime());
      
      currentCapacity = 0;
      currentSprintTickets = [];
    }
  });

  console.log(`Generated ${fakeSprints.length} fake sprints for tickets without sprints.`);
  return fakeSprints;
}

/**
 * Formats a date for sprint name (e.g., "12/22").
 */
function formatSprintDate(date: Date): string {
  const month = date.getMonth() + 1;
  const day = date.getDate();
  return `${month}/${day}`;
}

/**
 * Derives ticket-level estimate from a CSV row.
 *
 * Priority for schedule calculation:
 * - If Story Points are present → use them as-is.
 * - Else, if Original Estimate is present → use that numeric value as Story Points.
 * - Else, fall back to generic Estimate field via estimate processor.
 *
 * Both Story Points and Original Estimate are treated as "points" here and converted
 * to hours using HOURS_PER_STORY_POINT for schedule duration.
 */
function getTicketEstimate(row: CsvRow, rowNumber: number): TicketEstimate {
  let storyPoints: number | undefined;

  // 1) Try explicit Story Points column
  let spSource =
    extractField(row, 'Story Points', ['Story Points']) || '';

  // 2) If Story Points are empty, fall back to Original Estimate as SP source
  if (!spSource || spSource.trim() === '') {
    const originalEstimateRaw = extractField(row, 'Original Estimate', [
      'OriginalEstimate',
      'originalEstimate',
    ]);
    if (originalEstimateRaw && originalEstimateRaw.trim() !== '') {
      spSource = originalEstimateRaw;
    }
  }

  if (spSource && spSource.trim() !== '') {
    const sp = Number(spSource);
    if (!isNaN(sp) && sp > 0) {
      storyPoints = sp;
      return {
        storyPoints,
        baseHours: storyPoints * HOURS_PER_STORY_POINT,
      };
    }
  }

  // 3) Fallback: use generic Estimate field with existing processor
  const estimateValue = extractField(row, 'Estimate', [
    'Estimate',
    'estimate',
  ]);

  const processed = validateAndProcessEstimate(
    estimateValue,
    defaultConfig.defaultTeam,
    rowNumber
  );

  if (defaultConfig.defaultTeam.estimateType === 'story-points') {
    // When config is story-points, processed is SP; we can re-use it as storyPoints.
    storyPoints = processed;
    return {
      storyPoints,
      baseHours: processed * HOURS_PER_STORY_POINT,
    };
  }

  // Days-hours mode: processed is already hours, but we don't know Story Points
  return {
    storyPoints,
    baseHours: processed,
  };
}

/**
 * Builds a map of parent tickets to their subtasks.
 * Returns Map<parentKey, subtaskRows[]>
 */
function buildSubtaskMap(allRecords: CsvRow[]): Map<string, CsvRow[]> {
  const subtaskMap = new Map<string, CsvRow[]>();

  for (const row of allRecords) {
    const issueType = extractField(row, 'Issue Type', ['IssueType', 'issueType']) || '';
    const parentId = extractField(row, 'Parent Id', ['ParentId', 'parentId', 'Parent']) || '';
    const issueKey = extractField(row, 'Issue Key', ['ID', 'Id', 'id']) || '';

    // Check if this is a subtask (issue type is "Sub-task" or has a parent)
    if ((issueType === 'Sub-task' || parentId) && parentId && parentId.trim() !== '') {
      const parentKey = parentId.trim();
      
      if (parentKey && parentKey !== issueKey) {
        if (!subtaskMap.has(parentKey)) {
          subtaskMap.set(parentKey, []);
        }
        subtaskMap.get(parentKey)!.push(row);
      }
    }
  }

  return subtaskMap;
}

/**
 * Finds subtasks that match the given criteria.
 * Matching logic: ANY criteria matches (title tag OR component OR label)
 */
function findMatchingSubtasks(
  parentRow: CsvRow,
  subtaskRows: CsvRow[],
  matchCriteria: SubtaskMatchCriteria
): CsvRow[] {
  const matching: CsvRow[] = [];

  for (const subtask of subtaskRows) {
    let matches = false;

    // Check title tags
    if (matchCriteria.titleTags && matchCriteria.titleTags.length > 0) {
      const summary = extractField(subtask, 'Summary', ['Title', 'title']) || '';
      for (const tag of matchCriteria.titleTags) {
        if (summary.includes(tag)) {
          matches = true;
          break;
        }
      }
    }

    // Check components
    if (!matches && matchCriteria.components && matchCriteria.components.length > 0) {
      const component = extractField(subtask, 'Component', ['component']) || '';
      for (const comp of matchCriteria.components) {
        if (component === comp || component.includes(comp)) {
          matches = true;
          break;
        }
      }
    }

    // Check labels
    if (!matches && matchCriteria.labels && matchCriteria.labels.length > 0) {
      const labels = extractField(subtask, 'Labels', ['labels']) || '';
      const labelArray = labels.split(',').map(l => l.trim());
      for (const label of matchCriteria.labels) {
        if (labelArray.includes(label)) {
          matches = true;
          break;
        }
      }
    }

    if (matches) {
      matching.push(subtask);
    }
  }

  return matching;
}

/**
 * Calculates the estimate for a role based on the role configuration.
 */
function calculateRoleEstimate(
  roleConfig: RoleConfig,
  baseHours: number,
  parentRow: CsvRow,
  subtaskMap: Map<string, CsvRow[]>
): number {
  if (roleConfig.estimateMethod === 'percentage') {
    if (roleConfig.percentage === undefined) {
      return 0;
    }
    return baseHours * roleConfig.percentage;
  } else if (roleConfig.estimateMethod === 'subtasks') {
    if (!roleConfig.subtaskMatch) {
      return 0;
    }

    const parentKey = extractField(parentRow, 'Issue Key', ['ID', 'Id', 'id']) || '';
    const subtasks = subtaskMap.get(parentKey) || [];

    if (subtasks.length === 0) {
      return 0;
    }

    const matchingSubtasks = findMatchingSubtasks(parentRow, subtasks, roleConfig.subtaskMatch);

    if (matchingSubtasks.length === 0) {
      return 0;
    }

    // Sum estimates from matching subtasks
    let totalHours = 0;
    for (const subtask of matchingSubtasks) {
      const estimate = getTicketEstimate(subtask, 0);
      totalHours += estimate.baseHours;
    }

    return totalHours;
  }

  return 0;
}

/**
 * Main execution function.
 */
async function main() {
  // Load input CSV
  const csvContent = readFileSync(INPUT_CSV_PATH, 'utf-8');
  const records = parse(csvContent, {
    columns: true,
    skip_empty_lines: true,
    trim: true,
    relax_column_count: true,
  }) as CsvRow[];

  if (records.length === 0) {
    console.log(`No records found in ${INPUT_CSV_PATH}`);
    return;
  }

  // Load sprint map for lookup
  const sprintMap = loadSprintMap();

  // Load team configuration first (needed for fake sprint generation)
  const teamsConfig = loadTeamsConfigFromFile();

  // Filter out completed tickets (Status Category = "DONE")
  const nonCompletedRecords = records.filter((row) => !isCompletedTicket(row));

  // Generate fake sprints for tickets without sprints
  const fakeSprints = generateFakeSprints(nonCompletedRecords, sprintMap, teamsConfig);
  // Add fake sprints to sprint map
  for (const fakeSprint of fakeSprints) {
    sprintMap.set(fakeSprint.name, {
      endDate: fakeSprint.endDate,
      completeDate: fakeSprint.endDate, // Use end date as completion date for fake sprints
    });
  }

  console.log(
    `Filtered out ${records.length - nonCompletedRecords.length} completed tickets. Processing ${nonCompletedRecords.length} non-completed tickets.`
  );

  // Sort non-completed records: tickets with sprints first (by sprint End Date), then tickets without sprints
  const sortedRecords = [...nonCompletedRecords].sort((a, b) => {
    // Check for sprints
    const aSprintField = extractField(a, 'Sprint', ['sprint']);
    const bSprintField = extractField(b, 'Sprint', ['sprint']);
    const aLatestSprint = getLatestSprint(aSprintField);
    const bLatestSprint = getLatestSprint(bSprintField);

    // Tickets with sprints come before tickets without sprints
    if (aLatestSprint && !bLatestSprint) {
      return -1;
    }
    if (!aLatestSprint && bLatestSprint) {
      return 1;
    }

    // Both have sprints: sort by sprint End Date ascending
    if (aLatestSprint && bLatestSprint) {
      const aSprintEndDate = getSprintEndDate(aLatestSprint, sprintMap) || '';
      const bSprintEndDate = getSprintEndDate(bLatestSprint, sprintMap) || '';

      if (aSprintEndDate && bSprintEndDate) {
        return aSprintEndDate.localeCompare(bSprintEndDate);
      }
      if (aSprintEndDate) {
        return -1;
      }
      if (bSprintEndDate) {
        return 1;
      }
      // If sprint end dates not found, maintain order
      return 0;
    }

    // Both non-completed without sprints: maintain original order
    return 0;
  });

  // Build subtask map for subtask-based estimates
  const subtaskMap = buildSubtaskMap(records);

  // Load velocity context (teamsConfig already loaded above)
  const velocityContext = buildVelocityContext(teamsConfig);

  // Base start datetime for all teams
  const projectStart = loadProjectStartDateTime(teamsConfig);

  // Role-based cursors (replaces hardcoded baCursor, qaCursor, devCursors)
  const roleCursors: Record<string, Date> = {};

  // Initialize role cursors for all unique roles across all work types
  const allRoles = new Set<string>();
  const workTypeSequences = teamsConfig.workTypeSequences || {};
  
  // Initialize from workTypeSequences (new structure)
  if (Object.keys(workTypeSequences).length > 0) {
    for (const workType in workTypeSequences) {
      const workSequence = workTypeSequences[workType];
      for (const roleConfig of workSequence) {
        allRoles.add(roleConfig.role);
        if (!roleCursors[roleConfig.role]) {
          roleCursors[roleConfig.role] = new Date(projectStart.getTime());
        }
      }
    }
  } else {
    // Fallback to team.workSequence (backward compatibility)
    const teams = getTeamsArray(teamsConfig.teams);
    const includedTeams = teams.filter(team => team.includeInSchedule !== false);
    for (const team of includedTeams) {
      const workSequence = team.workSequence || DEFAULT_WORK_SEQUENCE;
      for (const roleConfig of workSequence) {
        allRoles.add(roleConfig.role);
        if (!roleCursors[roleConfig.role]) {
          roleCursors[roleConfig.role] = new Date(projectStart.getTime());
        }
      }
    }
  }

  const rows: TeamSegmentRow[] = [];

  sortedRecords.forEach((row, index) => {
    const rowNumber = index + 2; // header is row 1

    const issueKey = extractField(row, 'Issue Key', ['ID', 'Id', 'id']) || '';
    const summary =
      extractField(row, 'Summary', ['Title', 'title']) || '';
    const issueType =
      extractField(row, 'Issue Type', ['IssueType', 'issueType']) || '';
    const status =
      extractField(row, 'Status', ['status']) || '';
    
    // Extract latest sprint for this ticket
    const sprintField = extractField(row, 'Sprint', ['sprint']);
    const latestSprint = getLatestSprint(sprintField);
    
    // Extract epic link
    const epicLink = extractField(row, 'Epic Link', ['EpicLink', 'epicLink', 'Epic']);
    
    if (!issueKey) {
      return;
    }

    // Filter by planned issue types, if configured
    if (
      teamsConfig.plannedIssueTypes &&
      teamsConfig.plannedIssueTypes.length > 0 &&
      issueType &&
      !teamsConfig.plannedIssueTypes.includes(issueType)
    ) {
      return;
    }

    // Find matching team using Team, Component, Label, or Summary text
    const jiraTeam = findMatchingTeam(row, teamsConfig);

    // Get teams array for matching
    const teams = getTeamsArray(teamsConfig.teams);
    const includedTeams = teams.filter(team => team.includeInSchedule !== false);

    // Find the matching team configuration
    let matchingTeam: TeamConfig | undefined;
    
    if (jiraTeam) {
      // Try to find team by jiraTeam match
      matchingTeam = includedTeams.find(team => {
        const teamJiraTeams = team.matchRules?.jiraTeam;
        return Array.isArray(teamJiraTeams) && teamJiraTeams.includes(jiraTeam);
      });
    }

    // If not found by jiraTeam, try other match rules
    if (!matchingTeam) {
      const component = extractField(row, 'Component', ['component']) || '';
      const labels = extractField(row, 'Labels', ['labels']) || '';
      const summary = extractField(row, 'Summary', ['Title', 'title']) || '';

      for (const team of includedTeams) {
        const matchRules = team.matchRules;
        if (!matchRules) continue;

        // Check labels
        if (labels && matchRules.labels && Array.isArray(matchRules.labels) && matchRules.labels.length > 0) {
          const labelList = labels.split(',').map(l => l.trim());
          const matches = labelList.some(l =>
            matchRules.labels!.some(tl =>
              l.toLowerCase() === tl.toLowerCase() ||
              l.toLowerCase().includes(tl.toLowerCase()) ||
              tl.toLowerCase().includes(l.toLowerCase())
            )
          );
          if (matches) {
            matchingTeam = team;
            break;
          }
        }

        // Check summary text
        if (!matchingTeam && summary && matchRules.summaryText && Array.isArray(matchRules.summaryText) && matchRules.summaryText.length > 0) {
          const summaryLower = summary.toLowerCase();
          const matches = matchRules.summaryText.some(st => summaryLower.includes(st.toLowerCase()));
          if (matches) {
            matchingTeam = team;
            break;
          }
        }

        // Check components
        if (!matchingTeam && component && matchRules.components && Array.isArray(matchRules.components) && matchRules.components.length > 0) {
          const componentList = component.split(',').map(c => c.trim());
          const matches = componentList.some(c =>
            matchRules.components!.some(tc =>
              c.toLowerCase() === tc.toLowerCase() ||
              c.toLowerCase().includes(tc.toLowerCase()) ||
              tc.toLowerCase().includes(c.toLowerCase())
            )
          );
          if (matches) {
            matchingTeam = team;
            break;
          }
        }
      }
    }

    if (!matchingTeam) {
      return; // Skip if no matching team found
    }

    const estimate = getTicketEstimate(row, rowNumber);
    const baseHours = estimate.baseHours;
    const storyPoints = estimate.storyPoints;

    if (!isFinite(baseHours) || baseHours <= 0) {
      return;
    }

    // Get work sequence from workTypeSequences based on jiraTeam (new structure)
    // or fallback to team.workSequence (backward compatibility)
    let workSequence: RoleConfig[] | undefined;
    const workTypeSequences = teamsConfig.workTypeSequences || {};
    
    if (jiraTeam && workTypeSequences[jiraTeam]) {
      // Use work type sequence if jiraTeam matches a work type
      workSequence = workTypeSequences[jiraTeam];
    } else if (matchingTeam.workSequence) {
      // Fallback to team's workSequence (backward compatibility)
      workSequence = matchingTeam.workSequence;
    } else {
      // Use default sequence
      workSequence = DEFAULT_WORK_SEQUENCE;
    }

    // Process each role in the work sequence
    for (const roleConfig of workSequence) {
      // Check if ticket status matches role's statuses
      if (!status || !roleConfig.statuses.includes(status)) {
        continue; // Skip this role if status doesn't match
      }

      // Calculate role estimate
      const roleHours = calculateRoleEstimate(roleConfig, baseHours, row, subtaskMap);

      if (roleHours <= 0) {
        continue; // Skip if no estimate
      }

      // Round to 2 decimals
      const roleHoursRounded = Math.max(0, Number(roleHours.toFixed(2)));

      // Get cursor for this role
      const roleCursor = roleCursors[roleConfig.role] || new Date(projectStart.getTime());
      if (!roleCursors[roleConfig.role]) {
        roleCursors[roleConfig.role] = new Date(projectStart.getTime());
      }

      // Calculate duration with velocity
      const roleVelocity = getVelocityForSegment(roleConfig.role, jiraTeam, velocityContext);
      const roleDurationHours = scaleHoursWithVelocity(
        roleHoursRounded,
        roleVelocity,
        velocityContext
      );

      // Calculate start and end times
      const roleStart = new Date(roleCursor.getTime());
      const roleEnd = addWorkingHours(roleStart, roleDurationHours);

      // Add row for this role segment
      rows.push({
        issueKey,
        summary,
        issueType,
        status,
        jiraTeam,
        role: roleConfig.role,
        executionTeam: roleConfig.executionTeam,
        estimateHours: roleHoursRounded,
        storyPoints,
        latestSprint,
        epicLink,
        start: formatDateTimeLocal(roleStart),
        end: formatDateTimeLocal(roleEnd),
      });

      // Update cursor for this role
      roleCursors[roleConfig.role] = roleEnd;
    }
  });

  // Generate CSV output
  const header = [
    'Issue Key',
    'Summary',
    'Issue Type',
    'Status',
    'Jira Team',
    'Role',
    'Execution Team',
    'Estimate Hours',
    'Story Points',
    'Latest Sprint',
    'Epic Link',
    'Start',
    'End',
  ];

  const lines = rows.map((r) => {
    const escape = (value: string | number): string => {
      const str = String(value);
      if (str.includes(',') || str.includes('"') || str.includes('\n')) {
        return `"${str.replace(/"/g, '""')}"`;
      }
      return str;
    };

    return [
      escape(r.issueKey),
      escape(r.summary),
      escape(r.issueType),
      escape(r.status),
      escape(r.jiraTeam),
      escape(r.role),
      escape(r.executionTeam),
      escape(r.estimateHours),
      r.storyPoints !== undefined ? escape(r.storyPoints) : '',
      r.latestSprint !== undefined ? escape(r.latestSprint) : '',
      r.epicLink !== undefined ? escape(r.epicLink) : '',
      escape(r.start),
      escape(r.end),
    ].join(',');
  });

  const csvOutput = [header.join(','), ...lines].join('\n');
  writeFileSync(OUTPUT_CSV_PATH, csvOutput, 'utf-8');

  console.log(
    `Generated team schedule CSV with ${rows.length} rows at ${OUTPUT_CSV_PATH}`
  );
}

// Execute when run as a script
main().catch((error) => {
  console.error('Team schedule generation failed:', error);
  process.exit(1);
});



